def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Fill background cells lying between consecutive non-background cells
    # along any row or column.
    for r in range(h):
        marks = [c for c, v in enumerate(grid[r]) if v != background]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 3

    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != background]
        for a, b in zip(marks, marks[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 3

    return out
